        .key-insight-box p:last-child { margin-bottom: 0; }

        .key-insight-box strong {
            color: var(--gold);
        }

        .compatibility-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 12pt;
            margin: 12pt 0;
